import { _decorator, Component, CCString, CCInteger } from 'cc';
import { CCRecord, CCIndexRecord } from './CCRecord';

const { ccclass, property } = _decorator;

// No third argument! All three uses below map to the SAME CCClass type ID
// (CVHRecord_String_Integer), but they must have distinct entries arrays.
const Store = CCIndexRecord<string, number>(CCString, CCInteger);

@ccclass('CCRecordSameTypeDemo')
export class CCRecordSameTypeDemo extends Component {
    @property(CCString)
    public keepText = 'DO_NOT_RESET';

    @property(CCInteger)
    public keepNumber = 98765;

    // Stable, explicit initialization recommended while testing Editor commits.
    @property(Store)
    public first: Record<string, number> = new Store();

    @property(Store)
    public second: Record<string, number> = new Store();

    @property(Store)
    public third: Record<string, number> = new Store();

    // This also uses the identical autogenerated type, but the no-initializer
    // default is experimental in v0.8.x. Separate it from the safe controls.
    @property(CCRecord(CCString, CCInteger))
    public auto!: Record<string, number>;

    onLoad(): void {
        console.log('[SameType] independent stores:',
            this.first !== this.second,
            this.second !== this.third,
            'sentinels:', this.keepText, this.keepNumber);
    }
}
